import json

# Final attempt: left band = solid 8, right band = checkerboard 8/4, exterior = 0, special = 4

rows, cols = 20, 23

output = [[0 for _ in range(cols)] for _ in range(rows)]

# Left band (0-5): solid 8s, col 0 is marker 9
for r in range(6):
    for c in range(1, cols):
        output[r][c] = 8
    output[r][0] = 9

# Right band (10-15): checkerboard 8/4 (col 0 is 8, col 1 is 4, etc.), col 22 is marker 9
for r in range(10, 16):
    for c in range(22):
        if (r + c) % 2 == 0:
            output[r][c] = 8
        else:
            output[r][c] = 4
    output[r][22] = 9

# Special cell at (14,6) becomes 4
output[14][6] = 4

print("Final submission:")
for row in output:
    print(row)

